import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年10月1日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-10-01.md","filePath":"science-log/src/reconstructed/2026-10-01.md"}'),n={name:"science-log/src/reconstructed/2026-10-01.md"};function i(s,e,l,h,c,u){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="🔬-科学快报-2026年10月1日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年10月1日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年10月1日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年10月1日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05</p></blockquote><hr><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧊-古里雅冰帽新证据支持其冰芯时间尺度超过-10-万年" tabindex="-1">🧊 古里雅冰帽新证据支持其冰芯时间尺度超过 10 万年 <a class="header-anchor" href="#🧊-古里雅冰帽新证据支持其冰芯时间尺度超过-10-万年" aria-label="Permalink to &quot;🧊 古里雅冰帽新证据支持其冰芯时间尺度超过 10 万年&quot;">​</a></h3><p><strong>Additional evidence supports a timescale exceeding 100,000 years for the Guliya ice cap, Tibetan Plateau</strong><em>Science Advances (2026)</em></p><p>青藏高原古里雅冰帽是全球少有的中低纬度高海拔冰芯库，其记录能否延伸到末次间冰期一直存在争议。来自俄亥俄州立大学 Byrd 极地与气候研究中心（Thompson L.、Mosley-Thompson E. 等）的团队补充了新的测年与代用指标证据，支持该冰帽底部的冰芯年龄超过 10 万年。若成立，古里雅将与南极、格陵兰形成互补——提供中低纬度大气环流与粉尘输运的长期档案。这对重建亚洲季风与西风带的耦合历史具有关键价值，也对&quot;冰芯能否捕获完整间冰期信号&quot;给出直接判据。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aeh2912" target="_blank" rel="noreferrer">10.1126/sciadv.aeh2912</a></p><hr><h3 id="🧬-重新评估母血游离胎儿-dna-的-拓扑-指向更优产前诊断" tabindex="-1">🧬 重新评估母血游离胎儿 DNA 的&quot;拓扑&quot;，指向更优产前诊断 <a class="header-anchor" href="#🧬-重新评估母血游离胎儿-dna-的-拓扑-指向更优产前诊断" aria-label="Permalink to &quot;🧬 重新评估母血游离胎儿 DNA 的&quot;拓扑&quot;，指向更优产前诊断&quot;">​</a></h3><p><strong>Reappraising the topology of cell-free fetal DNA in maternal blood toward improved prenatal genetic testing</strong><em>Science Advances (2026)</em></p><p>无创产前检测（NIPT）依赖母血中游离胎儿 DNA（cffDNA），但其在血浆中的存在形式（片段长度、蛋白包裹、是否形成特定复合物）长期未被系统刻画。阿德莱德大学（Sparkes K.、Chamley L.、Larsen M. 等）团队重新审视了 cffDNA 的&quot;拓扑结构&quot;，揭示其分布与可检测性之间的关系。厘清这一结构层，有助于解释不同孕周、不同病理状态下检测灵敏度的差异，为提升胎儿遗传变异检出率与降低假阴性提供了分子层面的改进方向。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aef5425" target="_blank" rel="noreferrer">10.1126/sciadv.aef5425</a></p><hr><h3 id="⚛️-两质子、两正电子、四电子-兼具范德华特征的共价键" tabindex="-1">⚛️ 两质子、两正电子、四电子：兼具范德华特征的共价键 <a class="header-anchor" href="#⚛️-两质子、两正电子、四电子-兼具范德华特征的共价键" aria-label="Permalink to &quot;⚛️ 两质子、两正电子、四电子：兼具范德华特征的共价键&quot;">​</a></h3><p><strong>Two protons, two positrons, and four electrons: Covalent bond with van der Waals characteristics</strong><em>Science Advances (2026)</em></p><p>卢森堡大学物理与材料科学系（Charry J.、Tkatchenko A.）从理论上刻画了一种奇特的成键：由两个质子、两个正电子与四个电子组成、性质介于共价键与范德华相互作用之间的化学键。传统化学把键二分为&quot;强共价&quot;与&quot;弱范德华&quot;，而这类体系显示二者可以在同一势能面上连续过渡。它为&quot;化学键分类是不是人为切分&quot;提供了可计算的反例，并可能影响对正电子素（positronium）化学、低维材料层间作用与冷原子束缚态的理解。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aej0387" target="_blank" rel="noreferrer">10.1126/sciadv.aej0387</a></p><hr><h3 id="🧠-自身免疫失控升高-ebna-1-血清阳性儿童的ms风险" tabindex="-1">🧠 自身免疫失控升高 EBNA-1 血清阳性儿童的MS风险 <a class="header-anchor" href="#🧠-自身免疫失控升高-ebna-1-血清阳性儿童的ms风险" aria-label="Permalink to &quot;🧠 自身免疫失控升高 EBNA-1 血清阳性儿童的MS风险&quot;">​</a></h3><p><strong>Impaired control of autoimmunity increases pediatric multiple sclerosis risk in EBNA-1-seropositive children</strong><em>PNAS (2026)</em></p><p>EB 病毒（EBV）感染是儿童多发性硬化（MS）最强的环境风险因子，但为何只有部分血清阳性儿童发病仍不清楚。维也纳医科大学病毒学中心（Vietzen H. 等）的研究表明，宿主对自身免疫的&quot;控制能力&quot;（免疫调节/自身反应性清除的强弱）是决定风险的关键变量：在 EBNA-1 血清阳性的儿童中，自身免疫调控受损者发病风险显著上升。这支持&quot;EBV 提供扳机、宿主免疫约束决定是否走火&quot;的两步模型，也为识别高危儿童提供了可测的免疫学标志。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2607529123" target="_blank" rel="noreferrer">10.1073/pnas.2607529123</a></p><hr><h3 id="🦠-多发性硬化中的-谱系越界-cd3-b-细胞与-cd20-t-细胞" tabindex="-1">🦠 多发性硬化中的&quot;谱系越界&quot;：CD3⁺ B 细胞与 CD20⁺ T 细胞 <a class="header-anchor" href="#🦠-多发性硬化中的-谱系越界-cd3-b-细胞与-cd20-t-细胞" aria-label="Permalink to &quot;🦠 多发性硬化中的&quot;谱系越界&quot;：CD3⁺ B 细胞与 CD20⁺ T 细胞&quot;">​</a></h3><p><strong>T–B interactions yield CD3⁺ B cells and CD20⁺ T cells with pathogenic features in multiple sclerosis</strong><em>PNAS (2026)</em></p><p>经典免疫学中 CD3 是 T 细胞标志、CD20 是 B 细胞标志，二者本不交叉。慕尼黑大学（LMU）临床神经免疫学团队（Baier S. 等）在多发性硬化（MS）患者中观察到 T–B 细胞相互作用产生的&quot;谱系越界&quot;细胞——既表达 CD3 的 B 细胞与表达 CD20 的 T 细胞，且带有致病特征。这一现象挑战了淋巴细胞分类的刚性边界，提示 T/B 之间可能存在可塑的双向转化，对理解 MS 发病机制与设计靶向细胞治疗均有意义。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2605806123" target="_blank" rel="noreferrer">10.1073/pnas.2605806123</a></p><hr><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="👅-tastebench-从分子到可持续食品的多模态感官预测基准" tabindex="-1">👅 TasteBench：从分子到可持续食品的多模态感官预测基准 <a class="header-anchor" href="#👅-tastebench-从分子到可持续食品的多模态感官预测基准" aria-label="Permalink to &quot;👅 TasteBench：从分子到可持续食品的多模态感官预测基准&quot;">​</a></h3><p><strong>TasteBench: Multimodal Benchmark for Sensory Prediction, from Molecules to Sustainable Foods</strong><em>arXiv (2026)</em></p><p>可持续蛋白研发缺少像分子对接或密度泛函理论那样的快速计算代理——判断一种新食物是否&quot;尝起来像&quot;动物源目标，目前只能靠昂贵的人工感官评审，卡住了&quot;设计-构建-测试&quot;循环。Google 等机构（Anna T. Thomas、Benjamin Sanchez-Lengeling 等）提出 TasteBench：一个多模态基准与隐私保护的竞赛平台，用于感官预测。它把&quot;味觉&quot;这一难量化的人类感知变成可测量的机器学习任务，为替代蛋白的快速迭代建立公共评测标尺。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2610.02599" target="_blank" rel="noreferrer">2610.02599</a></p><hr><h3 id="🩺-用可验证、反馈驱动的语言模型回答临床试验证据表上的临床问题" tabindex="-1">🩺 用可验证、反馈驱动的语言模型回答临床试验证据表上的临床问题 <a class="header-anchor" href="#🩺-用可验证、反馈驱动的语言模型回答临床试验证据表上的临床问题" aria-label="Permalink to &quot;🩺 用可验证、反馈驱动的语言模型回答临床试验证据表上的临床问题&quot;">​</a></h3><p><strong>Answering clinicians&#39; questions over trial evidence tables with verifiable, feedback-driven language models</strong><em>arXiv (2026)</em></p><p>系统综述把临床试验压缩成证据表，但医生只能靠数据库查询来提问，且许多问题涉及表格并未记录的属性（如药物靶点类别、统一化终点）。作者（Manan Roy Choudhury 等）提出 FD-SCoPE 框架：它同时回答&quot;表内&quot;与&quot;表外&quot;两类问题，并暴露所用查询、选中的试验与推导规则以便核验。在多模态/知识密集型医疗场景下，这把 LLM 从&quot;黑箱作答&quot;推向&quot;可审计的推理链&quot;，对循证医学尤为关键。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2610.02576" target="_blank" rel="noreferrer">2610.02576</a></p><hr><h3 id="⚡-通过有效提示提升-llm-生成代码的能效" tabindex="-1">⚡ 通过有效提示提升 LLM 生成代码的能效 <a class="header-anchor" href="#⚡-通过有效提示提升-llm-生成代码的能效" aria-label="Permalink to &quot;⚡ 通过有效提示提升 LLM 生成代码的能效&quot;">​</a></h3><p><strong>Improving the Energy-Efficiency of the Code Generated by LLMs through Effective Prompting</strong><em>arXiv (2026)</em></p><p>AI 辅助编程普及后，生成软件的能耗成为实质问题。前沿 LLM 极少按&quot;生成代码的执行效率与能耗&quot;来评测，而非仅看功能正确性。作者（Ritika Rekhi 等）系统研究了提示方式对生成代码能耗的影响，探索能否在提示层面引导模型产生更省电的实现。结论指向一个被忽视的维度：代码质量不只有&quot;对不对&quot;，还有&quot;耗多少电&quot;，而提示工程是可以施加影响的杠杆。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2610.02571" target="_blank" rel="noreferrer">2610.02571</a></p><hr><h3 id="🗣️-用多元偏好优化缓解社交谄媚" tabindex="-1">🗣️ 用多元偏好优化缓解社交谄媚 <a class="header-anchor" href="#🗣️-用多元偏好优化缓解社交谄媚" aria-label="Permalink to &quot;🗣️ 用多元偏好优化缓解社交谄媚&quot;">​</a></h3><p><strong>Mitigating Social Sycophancy via Pluralistic Preference Optimization</strong><em>arXiv (2026)</em></p><p>情感/关系建议已成为生成式 AI 的高频用途，但语言模型存在&quot;谄媚&quot;（sycophancy）：比人类更频繁地肯定用户，可能让用户更自信、更不愿修复关系中的冲突。以往缓解谄媚多在&quot;有标准答案&quot;的事实场景进行，而这里没有 ground truth。作者（Stephane Hatgis-Kessell、Myra Cheng 等）提出多元偏好优化，在价值多元、无唯一正确答案的社交场景下校准模型行为，把&quot;对齐&quot;从事实层推进到价值层。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2610.02568" target="_blank" rel="noreferrer">2610.02568</a></p><hr><h3 id="🔍-学习-下一步调查什么-面向长时程科研智能体的元推理" tabindex="-1">🔍 学习&quot;下一步调查什么&quot;：面向长时程科研智能体的元推理 <a class="header-anchor" href="#🔍-学习-下一步调查什么-面向长时程科研智能体的元推理" aria-label="Permalink to &quot;🔍 学习&quot;下一步调查什么&quot;：面向长时程科研智能体的元推理&quot;">​</a></h3><p><strong>Learning What to Investigate Next: Meta-Reasoning for Long-Horizon Research Agents</strong><em>arXiv (2026)</em></p><p>长时程科研智能体必须在证据累积过程中同时决定&quot;如何调查&quot;与&quot;下一步调查什么&quot;。这很难学，因为此类决策在长执行轨迹中稀疏，且后果可能要在若干步之后才显现。作者（Ankur Samanta、Paul Sajda、Kaveh Hassani 等）提出 MIRA（面向迭代科研智能体的元推理）——一种把&quot;研究资源分配&quot;与&quot;具体执行&quot;分离的层级架构，外层循环做元推理。它针对的正是自主科研智能体最稀缺的能力：在不确定中主动选题，而非仅执行既定步骤。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2610.02525" target="_blank" rel="noreferrer">2610.02525</a></p><hr><blockquote><p>📅 日期：2026-10-01 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 期号：（第 ? 期 · 事后重建版）</p></blockquote>',56)])])}const q=a(n,[["render",i]]);export{d as __pageData,q as default};
